function jieAround(y) {
  const ev = [];
  for (const yy of [y - 1, y, y + 1]) for (const [lon, name, zhi] of JIE) ev.push({ utc: solarTermUtc(yy, lon), name, zhi, lon });
  return ev.sort((a, b) => a.utc - b.utc);
}

/* ---------- 균시차 (분) ---------- */
function equationOfTime(utcMs) {
  const jd = utcMs / DAY + UNIX_JD, T = (jd - J2000) / 36525;
  const L0 = rad(280.46646 + 36000.76983*T), M = rad(357.52911 + 35999.05029*T), e = 0.016708634 - 0.000042037*T;
  const eps = rad(23.439291 - 0.0130042*T), y = Math.tan(eps/2) ** 2;
  const E = y*Math.sin(2*L0) - 2*e*Math.sin(M) + 4*e*y*Math.sin(M)*Math.cos(2*L0) - 0.5*y*y*Math.sin(4*L0) - 1.25*e*e*Math.sin(2*M);
  return E * 180 / Math.PI * 4;
}

/* ---------- 한국 음양력: korean-lunar-calendar 0.4.0 표 기반 변환 ---------- */
const _krCalendar = new root.KoreanLunarCalendar();
const dayIndex = (y,m,d) => Math.floor(Date.UTC(y,m-1,d)/DAY);
function fromDayIndex(i){const t=new Date(i*DAY);return [t.getUTCFullYear(),t.getUTCMonth()+1,t.getUTCDate()];}
function solarToLunar(y,m,d){
 if(!_krCalendar.setSolarDate(y,m,d))throw new Error('존재하지 않거나 지원 범위 밖의 양력 날짜입니다. (1900~2050년)');
 const q=_krCalendar.getLunarCalendar();return {year:q.year,month:q.month,day:q.day,leap:!!q.intercalation};
}
function lunarToSolar(y,m,d,leap=false){
 if(!_krCalendar.setLunarDate(y,m,d,!!leap))throw new Error('존재하지 않는 음력 날짜 또는 윤달입니다. 음력은 2050년 11월 18일까지 지원합니다.');
 const q=_krCalendar.getSolarCalendar();return [q.year,q.month,q.day];
}

/* ---------- 간지 기본 ---------- */
const mod = (a, n) => ((a % n) + n) % n;
const dayGzIndex = (y, m, d) => mod(dayIndex(y, m, d) + 2440588 + 49, 60); // JDN+49
const gz = i => ({ s: mod(i, 10), b: mod(i, 12) });
const gzIndexOf = (s, b) => { for (let i = 0; i < 60; i++) if (i % 10 === s && i % 12 === b) return i; return -1; };
const MONTH_STEM_START = [2,4,6,8,0,2,4,6,8,0]; // 년간 → 인월 천간
const HOUR_STEM_START = [0,2,4,6,8,0,2,4,6,8];  // 일간 → 자시 천간
const TEN = { same: ['비견','식신','편재','편관','편인'], diff: ['겁재','상관','정재','정관','정인'] };
function tenGod(ds, os) { if (os == null) return null; const rel = mod(GAN_EL[os] - GAN_EL[ds], 5); return (ds % 2 === os % 2 ? TEN.same : TEN.diff)[rel]; }
const HIDDEN = [[9],[5,9,7],[0,2,4],[1],[4,1,9],[2,6,4],[3,5],[5,3,1],[6,8,4],[7],[4,7,3],[8,0]]; // 지장간(정기 먼저)
const STAGES = ['장생','목욕','관대','건록','제왕','쇠','병','사','묘','절','태','양'];
const STAGE_START = [11,6,2,9,2,9,5,0,8,3]; // 각 천간의 장생지
function twelveStage(s, b) { const st = STAGE_START[s]; return STAGES[s % 2 === 0 ? mod(b - st, 12) : mod(st - b, 12)]; }

/* ---------- 신살 (bazi-skill 표 + 한국 통용 신살) ---------- */
const P = s => [...s].map(c => ZHI.indexOf(c));
const TIANYI = ['丑未','子申','亥酉','亥酉','丑未','子申','丑未','寅午','卯巳','卯巳'].map(P);
const WENCHANG = P('巳午申酉申酉亥子寅卯'), YANGIN = P('卯辰午未午未酉戌子丑');
const SANHE_GRP = b => [8,0,4].includes(b) ? 4 : [2,6,10].includes(b) ? 1 : [5,9,1].includes(b) ? 3 : 0; // 수,화,금,목 국
const BY_GRP = { // 국 오행 → 지지
  yeokma: { 4: 2, 1: 8, 3: 11, 0: 5 }, dohwa: { 4: 9, 1: 3, 3: 6, 0: 0 }, hwagae: { 4: 4, 1: 10, 3: 1, 0: 7 },
  jangseong: { 4: 0, 1: 6, 3: 9, 0: 3 }, geopsal: { 4: 5, 1: 11, 3: 2, 0: 8 } };
const HONGYEOM = P('午午寅未辰辰戌酉子申');
const GOEGANG = [[6,4],[6,10],[8,4],[8,10],[4,10]];
const BAEKHO = [[0,4],[1,7],[2,10],[3,1],[4,4],[8,10],[9,1]];
const WONJIN = [7,6,9,8,11,10,1,0,3,2,5,4];
function kongmang(ds, db) { const st = mod(db - ds, 12); return [mod(st - 2, 12), mod(st - 1, 12)]; }
function shinsal(p) {
  const [H, D, M, Y] = p; const out = [];
  const pillars = [['년', Y], ['월', M], ['일', D], ['시', H]].filter(x => x[1]);
  const at = (targets, label, desc) => { const t = [].concat(targets); const hit = pillars.filter(([, q]) => t.includes(q.b)).map(([n]) => n + '지'); if (hit.length) out.push({ name: label, at: hit, desc }); };
  at([...TIANYI[D.s], ...TIANYI[Y.s]], '천을귀인', '어려울 때 돕는 사람이 나타나는 가장 큰 길신');
  at([WENCHANG[D.s]], '문창귀인', '학문과 글, 시험에 유리한 기운');
  at([BY_GRP.yeokma[SANHE_GRP(Y.b)], BY_GRP.yeokma[SANHE_GRP(D.b)]], '역마살', '이동과 변화가 많고 활동 범위가 넓음');
  at([BY_GRP.dohwa[SANHE_GRP(Y.b)], BY_GRP.dohwa[SANHE_GRP(D.b)]], '도화살', '사람을 끄는 매력과 인기');
  at([BY_GRP.hwagae[SANHE_GRP(Y.b)], BY_GRP.hwagae[SANHE_GRP(D.b)]], '화개살', '예술성과 종교·철학적 사색');
  at([BY_GRP.jangseong[SANHE_GRP(Y.b)], BY_GRP.jangseong[SANHE_GRP(D.b)]], '장성살', '조직을 이끄는 리더의 기운');
  at([YANGIN[D.s]], D.s % 2 === 0 ? '양인살' : '양인(음간)', '강한 추진력과 승부욕');
  at([HONGYEOM[D.s]], '홍염살', '이성에게 끌리는 매력이 강함');
  const km = kongmang(D.s, D.b); const kmHit = pillars.filter(([n, q]) => n !== '일' && km.includes(q.b)).map(([n]) => n + '지');
  if (kmHit.length) out.push({ name: '공망', at: kmHit, desc: `${ZHIK[km[0]]}${ZHIK[km[1]]} 공망. 해당 자리의 기운이 비어 집착을 내려놓을 때 풀림` });
  if (GOEGANG.some(([s, b]) => D.s === s && D.b === b)) out.push({ name: '괴강살', at: ['일주'], desc: '강한 카리스마와 결단력' });
  const bh = pillars.filter(([, q]) => BAEKHO.some(([s, b]) => q.s === s && q.b === b)).map(([n]) => n + '주');
  if (bh.length) out.push({ name: '백호대살', at: bh, desc: '강한 기운. 추진력이 크지만 안전에 유의' });
  if (WONJIN[Y.b] === D.b) out.push({ name: '원진(년-일)', at: ['년지','일지'], desc: '가까운 관계에서 미묘한 서운함이 생기기 쉬움' });
  return out;
}

/* ---------- 합·충·형·파·해 ---------- */
const STEM_HAP = [[0,5,'토'],[1,6,'금'],[2,7,'수'],[3,8,'목'],[4,9,'화']];
const STEM_CHUNG = [[0,6],[1,7],[2,8],[3,9]];
const YUKHAP = [[0,1,'토'],[2,11,'목'],[3,10,'화'],[4,9,'금'],[5,8,'수'],[6,7,'토']];
const SAMHAP = [[[8,0,4],'수'],[[11,3,7],'목'],[[2,6,10],'화'],[[5,9,1],'금']];
const PA = [[0,9],[1,4],[2,11],[3,6],[5,8],[7,10]];
const HAE = [[0,7],[1,6],[2,5],[3,4],[8,11],[9,10]];
const HYEONG = [[[2,5,8],'인사신 삼형(지세지형)'],[[1,10,7],'축술미 삼형(무은지형)'],[[0,3],'자묘 상형(무례지형)']];
function relations(p) {
  const names = ['시', '일', '월', '년'];
  const L = p.map((q, i) => q && { n: names[i], ...q }).filter(Boolean);
  const out = []; const pair = (a, b) => `${a.n}-${b.n}`;
  for (let i = 0; i < L.length; i++) for (let j = i + 1; j < L.length; j++) {
    const a = L[i], b = L[j];
    for (const [x, y, e] of STEM_HAP) if ((a.s === x && b.s === y) || (a.s === y && b.s === x)) out.push({ type: '천간합', at: pair(a, b), text: `${GAN[a.s]}${GAN[b.s]}합${e}` });
    for (const [x, y] of STEM_CHUNG) if ((a.s === x && b.s === y) || (a.s === y && b.s === x)) out.push({ type: '천간충', at: pair(a, b), text: `${GAN[a.s]}${GAN[b.s]}충` });
    for (const [x, y, e] of YUKHAP) if ((a.b === x && b.b === y) || (a.b === y && b.b === x)) out.push({ type: '육합', at: pair(a, b), text: `${ZHI[a.b]}${ZHI[b.b]}합${e}` });
    if (mod(a.b - b.b, 12) === 6) out.push({ type: '충', at: pair(a, b), text: `${ZHI[a.b]}${ZHI[b.b]}충` });
    for (const [x, y] of PA) if ((a.b === x && b.b === y) || (a.b === y && b.b === x)) out.push({ type: '파', at: pair(a, b), text: `${ZHI[a.b]}${ZHI[b.b]}파` });
    for (const [x, y] of HAE) if ((a.b === x && b.b === y) || (a.b === y && b.b === x)) out.push({ type: '해', at: pair(a, b), text: `${ZHI[a.b]}${ZHI[b.b]}해` });
    if (WONJIN[a.b] === b.b) out.push({ type: '원진', at: pair(a, b), text: `${ZHI[a.b]}${ZHI[b.b]}원진` });
    if (a.b === b.b && [4, 6, 9, 11].includes(a.b)) out.push({ type: '자형', at: pair(a, b), text: `${ZHI[a.b]}${ZHI[b.b]}자형` });
  }
  const bs = L.map(q => q.b);
  for (const [g, e] of SAMHAP) { const c = g.filter(x => bs.includes(x)).length; if (c === 3) out.push({ type: '삼합', at: '', text: g.map(x => ZHI[x]).join('') + `삼합 ${e}국` }); else if (c === 2 && bs.includes(g[1])) out.push({ type: '반합', at: '', text: g.filter(x => bs.includes(x)).map(x => ZHI[x]).join('') + `반합 ${e}` }); }
  for (const [g, name] of HYEONG) { const c = g.filter(x => bs.includes(x)).length; if (c >= 2 && (g.length === 2 || c >= 2)) out.push({ type: '형', at: '', text: (c === g.length ? '' : '일부 ') + name }); }
  return out;
}

/* ---------- 신강·신약, 용신 (억부·조후, 참고용) ---------- */
// 가중치: 월지 30, 일지 15, 시지 15, 년지 10, 천간 각 10 (일간 제외) = 100
function strength(p) {
  const [H, D, M, Y] = p, d = GAN_EL[D.s];
  const items = [[M.b, 'b', 30], [D.b, 'b', 15], [Y.b, 'b', 10], [Y.s, 's', 10], [M.s, 's', 10]];
  if (H) items.push([H.b, 'b', 15], [H.s, 's', 10]);
  let tot = 0, sup = 0;
  for (const [v, k, w] of items) { const e = k === 's' ? GAN_EL[v] : ZHI_EL[v]; tot += w; if (e === d || e === mod(d - 1, 5)) sup += w; }
  const score = Math.round(sup / tot * 100);
  const label = score >= 75 ? '극신강' : score >= 55 ? '신강' : score >= 45 ? '중화' : score >= 25 ? '신약' : '극신약';
  return { score, label };
}
function elementCount(p) { const c = [0,0,0,0,0]; for (const q of p) if (q) { c[GAN_EL[q.s]]++; c[ZHI_EL[q.b]]++; } return c; }
function yongsin(p, st, cnt) {
  const d = GAN_EL[p[1].s], M = p[2].b; const tg = e => mod(e - d, 5); // 0비겁 1식상 2재성 3관성 4인성
  const byTg = [0,0,0,0,0]; cnt.forEach((c, e) => byTg[tg(e)] += c);
  let el, why;
  if (st.score >= 55) {
    if (byTg[0] >= byTg[4]) { el = mod(d + 3, 5); why = '비겁이 강해 관성으로 다스림'; }
    else { el = mod(d + 2, 5); why = '인성이 강해 재성으로 조절'; }
    if (byTg[1] === 0 && byTg[2] === 0 && byTg[3] === 0) { el = mod(d + 1, 5); why = '기운을 설기할 식상이 필요'; }
  } else if (st.score < 45) {
    if (byTg[3] >= byTg[2] && byTg[3] >= byTg[1]) { el = mod(d + 4, 5); why = '관성이 강해 인성으로 살인상생'; }
    else if (byTg[2] >= byTg[1]) { el = d; why = '재성이 강해 비겁으로 감당'; }
    else { el = mod(d + 4, 5); why = '식상이 강해 인성으로 제어'; }
  } else { el = cnt.indexOf(Math.min(...cnt)); why = '중화에 가까워 부족한 오행을 보충'; }
  let johu = null;
  if ([5, 6, 7].includes(M) && cnt[1] >= 3) johu = { el: 4, why: '여름생에 화가 많아 수로 식혀야 함' };
  if ([11, 0, 1].includes(M) && cnt[4] >= 3) johu = { el: 1, why: '겨울생에 수가 많아 화로 데워야 함' };
  return { el, why, johu, method: '억부법 + 조후 보정 (참고용)' };
}

/* ---------- 메인 ---------- */
/**
 * @param {object} o
 *  calendar: 'solar'|'lunar', year, month, day, leap(bool, 음력 윤달)
 *  hour, minute: 출생 시각(한국 벽시계). 모르면 null
 *  gender: 'M'|'F'
 *  longitude: 출생지 경도 (기본 서울 126.978)
 *  timeMode: 'lmt'(경도 보정, 기본) | 'apparent'(균시차까지) | 'standard'(보정 없음, 서머타임만 제거)
 *  zishi: 'unified'(23시부터 다음 날 일주, 기본) | 'split'(야자시: 23~24시는 당일 일주, 시간은 다음 날 자시)
 */
function calc(o) {
  const notes = [];
  let [y, m, d] = [o.year, o.month, o.day];
  if(![y,m,d].every(Number.isInteger)||y<1900||y>2050)throw new Error('생년월일은 1900~2050년의 정수로 입력해 주세요.');
  if(o.hour!=null&&(!Number.isInteger(o.hour)||o.hour<0||o.hour>23||!Number.isInteger(o.minute??0)||(o.minute??0)<0||(o.minute??0)>59))throw new Error('출생 시간은 0~23시, 분은 0~59분으로 입력해 주세요.');
  if(o.timeMode&&!['lmt','apparent','standard','fixed'].includes(o.timeMode))throw new Error('시간 보정 방식이 올바르지 않습니다.');
  if(o.zishi&&!['unified','split'].includes(o.zishi))throw new Error('자시 기준이 올바르지 않습니다.');
  if(o.longitude!=null&&(!Number.isFinite(o.longitude)||Math.abs(o.longitude)>180))throw new Error('출생지 경도가 올바르지 않습니다.');
  if(o.timeMode==='fixed'&&(!Number.isFinite(o.fixedOffset??540)||Math.abs(o.fixedOffset??540)>840))throw new Error('고정 시간대가 올바르지 않습니다.');
  if (o.calendar === 'lunar') { [y, m, d] = lunarToSolar(o.year, o.month, o.day, o.leap); notes.push(`음력 ${o.year}.${o.month}.${o.day}${o.leap ? '(윤)' : ''} → 양력 ${y}.${m}.${d}`); }
  solarToLunar(y,m,d); // strict civil-date validation before Date.UTC can normalize invalid days
  const timeKnown = o.hour != null;
  const hh = timeKnown ? o.hour : 12, mm = timeKnown ? (o.minute || 0) : 0;
  const fixed = o.timeMode === 'fixed', fo = o.fixedOffset ?? 540; // 'fixed': 검증용(고정 시간대, 보정 없음)
  const w = fixed ? { utc: Date.UTC(y, m - 1, d, hh, mm) - fo * 60000, notes: [] } : krWallToUtc(y, m, d, hh, mm, o.dstFold); notes.push(...w.notes);
  const utc = w.utc, off = fixed ? fo : krOffsetAt(utc), std = fixed ? fo : krStdOffsetAt(utc);
  if (timeKnown && off !== std) notes.push('서머타임 시행 기간 출생이라 1시간을 보정했습니다.');
  const lon = o.longitude ?? 126.978, mode = o.timeMode || 'lmt';
  let localMin = mode === 'standard' || fixed ? std : lon * 4;
  let eot = 0; if (mode === 'apparent') { eot = equationOfTime(utc); localMin += eot; }
  const local = new Date(utc + localMin * 60000);
  const L = { y: local.getUTCFullYear(), m: local.getUTCMonth() + 1, d: local.getUTCDate(), h: local.getUTCHours(), mi: local.getUTCMinutes() };
  const corrMin = Math.round(localMin - off);
  // 년주·월주: 절입 순간 비교
  const ev = jieAround(y); let cur = null, next = null, prev = null;
  for (let i = 0; i < ev.length; i++) { if (ev[i].utc <= utc) { cur = ev[i]; prev = ev[i]; } else { next = ev[i]; break; } }
  const lichun = solarTermUtc(y, 315), sajuYear = utc >= lichun ? y : y - 1;
  const Y = gz(mod(sajuYear - 4, 60));
  const mb = cur.zhi, M = { s: mod(MONTH_STEM_START[Y.s] + mod(mb - 2, 12), 10), b: mb };
  // 일주·시주: 보정된 지방시
  let dayShift = 0, hourStemDay = 0;
  const minOfDay = L.h * 60 + L.mi;
  if (timeKnown && minOfDay >= 23 * 60) { if ((o.zishi || 'unified') === 'unified') dayShift = 1; else hourStemDay = 1; }
  const dIdx = mod(dayGzIndex(L.y, L.m, L.d) + dayShift, 60), D = gz(dIdx);
  let H = null;
  if (timeKnown) { const hb = Math.floor(mod(minOfDay + 60, 1440) / 120); const baseS = gz(mod(dIdx + hourStemDay, 60)).s; H = { s: mod(HOUR_STEM_START[baseS] + hb, 10), b: hb }; }
  if (timeKnown) { const edge = [60,180,300,420,540,660,780,900,1020,1140,1260,1380].some(b => Math.abs(minOfDay - b) <= 10); if (edge) notes.push('보정 시각이 시(時) 경계 10분 이내입니다. 출생 시각이 조금만 달라도 시주가 바뀔 수 있습니다.'); }
  if (next && next.utc - utc < 6 * 3600000 || utc - cur.utc < 6 * 3600000) notes.push(`절입(${utc - cur.utc < 6 * 3600000 ? cur.name : next.name}) 시각 6시간 이내 출생입니다. 월주 판단에 출생 시각이 중요합니다.`);
  const sameDayTerms = !timeKnown ? ev.filter(e=>{const t=new Date(e.utc+krOffsetAt(e.utc)*60000);return t.getUTCFullYear()===y&&t.getUTCMonth()+1===m&&t.getUTCDate()===d;}) : [];
  const uncertainty={month:sameDayTerms.length>0,year:sameDayTerms.some(e=>e.lon===315)};
  if (!timeKnown) notes.push('출생 시각을 몰라 시주를 제외했습니다.');
  if(uncertainty.month)notes.push('출생일에 '+sameDayTerms.map(e=>e.name).join('·')+' 절입이 있어 '+(uncertainty.year?'년주·월주':'월주')+'가 출생 시간에 따라 달라집니다. 현재는 정오 가정값이며 확정 결과가 아닙니다.');
  const pillars = [H, D, M, Y]; // 시 일 월 년
  // 대운
  let daeun = null;
  if (o.gender === 'M' || o.gender === 'F') {
    const yangYear = Y.s % 2 === 0, fwd = yangYear === (o.gender === 'M');
    const target = fwd ? next.utc : cur.utc;
    const days = Math.abs(target - utc) / DAY, ageF = days / 3;
    const yrs = Math.floor(ageF), mos = Math.floor((ageF - yrs) * 12);   // 3일=1년, 1일=4개월 (내림)
    const daeunsu = Math.max(1, Math.round(days / 3));                    // 한국식 대운수: 나머지 2일은 올림, 1일은 버림
    const mIdx = gzIndexOf(M.s, M.b), list = [];
    for (let k = 1; k <= 10; k++) { const g = gz(mod(mIdx + (fwd ? k : -k), 60)); const age = daeunsu + (k - 1) * 10; list.push({ age, year: y + age, s: g.s, b: g.b, ten: tenGod(D.s, g.s), stage: twelveStage(D.s, g.b) }); }
    daeun = { forward: fwd, startAge: yrs, startMonths: mos, daeunsu, list };
  }
  const cnt = elementCount(pillars), st = strength(pillars);
  const ys = yongsin(pillars, st, cnt);
  const detail = pillars.map((q, i) => q && ({
    label: ['시주','일주','월주','년주'][i], s: q.s, b: q.b,
    stem: GAN[q.s], branch: ZHI[q.b], stemK: GANK[q.s], branchK: ZHIK[q.b],
    stemEl: GAN_EL[q.s], branchEl: ZHI_EL[q.b],
    stemTen: i === 1 ? '일간' : tenGod(D.s, q.s), branchTen: tenGod(D.s, HIDDEN[q.b][0]),
    hidden: HIDDEN[q.b].map(h => ({ stem: GAN[h], ten: tenGod(D.s, h) })), stage: twelveStage(D.s, q.b)
  }));
  const seun = []; for (let yy = new Date().getUTCFullYear() - 1; yy <= new Date().getUTCFullYear() + 3; yy++) { const g = gz(mod(yy - 4, 60)); seun.push({ year: yy, s: g.s, b: g.b, ten: tenGod(D.s, g.s) }); }
  return {
    input: { solar: [y, m, d], time: timeKnown ? [hh, mm] : null },
    corrected: { y: L.y, m: L.m, d: L.d, h: L.h, mi: L.mi, minutes: corrMin, mode, longitude: lon, eot: Math.round(eot * 10) / 10 },
    lunar: solarToLunar(y, m, d), uncertainty, sajuYear, animal: ANIMAL[Y.b],
    jie: { current: cur.name, currentAt: cur.utc, next: next && next.name, nextAt: next && next.utc },
    pillars, detail, dayMaster: D.s, elements: cnt, strength: st, yongsin: ys,
    shinsal: shinsal(pillars), relations: relations(pillars), daeun, seun, notes
  };
}

